var accountLabel = regexp.MustCompile(`^[a-z0-9][a-z0-9_-]{0,31}$`)

func vocabulary(s string) map[string]bool {
	out := map[string]bool{}
	for _, v := range strings.Fields(s) {
		out[v] = true
	}
	return out
}

